import { symbolSvg, wordmarkPaths } from '@madar/brand';
import { cn } from '@/lib/cn';

/** Orbital symbol. Markup is generated by our own brand geometry (no user input). */
export function Symbol({ size = 40, theme = 'dark', className, id = 'sym' }: { size?: number; theme?: 'dark' | 'light'; className?: string; id?: string }) {
  return (
    <svg viewBox="0 0 200 200" width={size} height={size} className={className} aria-hidden="true" dangerouslySetInnerHTML={{ __html: symbolSvg({ theme, id }) }} />
  );
}

export function Wordmark({ height = 18, color = 'currentColor', className }: { height?: number; color?: string; className?: string }) {
  const w = wordmarkPaths({ height: 100, color, stroke: 7.6 });
  const width = (w.width / 100) * height;
  return (
    <svg viewBox={`-4 -4 ${w.width + 8} 108`} width={width} height={height} className={className} role="img" aria-label="MADAR" dangerouslySetInnerHTML={{ __html: w.svg }} />
  );
}

export function LogoHorizontal({ className, theme = 'dark', compact = false }: { className?: string; theme?: 'dark' | 'light'; compact?: boolean }) {
  return (
    <span className={cn('inline-flex items-center gap-3', className)}>
      <Symbol size={compact ? 30 : 38} theme={theme} id={`h-${theme}`} />
      <Wordmark height={compact ? 13 : 15} color={theme === 'dark' ? '#F6F4F1' : '#0B0E1A'} />
    </span>
  );
}

/** Stacked bilingual lockup as on the brand board. */
export function LogoStacked({ className, scale = 1 }: { className?: string; scale?: number }) {
  return (
    <div className={cn('flex flex-col items-center text-center', className)}>
      <Symbol size={150 * scale} id="stacked" className="drop-shadow-[0_0_40px_rgba(139,124,246,0.45)]" />
      <Wordmark height={54 * scale} color="#F6F4F1" className="mt-4" />
      <span lang="ar" dir="rtl" className="arabic mt-3 text-lavender-soft" style={{ fontSize: 40 * scale, lineHeight: 1.1 }}>
        مَدار
      </span>
      <span className="tagline mt-5 text-sand/85" style={{ fontSize: Math.max(11, 15 * scale) }}>
        The city in motion.
      </span>
    </div>
  );
}
